    "project/contracts/core/storages/AccountStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

import { LockedValues } from "../storages/QuoteStorage.sol";

/// @notice Classification of liquidation severity based on timing and deficit
/// @dev Determines how remaining funds are distributed and who pays what.
///      NONE = not liquidated
///      NORMAL = liquidated on time (no deficit)
///      LATE = liquidated with small deficit (at least LF but at most LF + CVA)
///      OVERDUE = liquidated with large deficit (more than LF + CVA)
enum LiquidationType {
	NONE,
	NORMAL,
	LATE,
	OVERDUE
}

/// @notice PartyB's solvency state during a force close operation
/// @dev Determines what happens after force close completes.
///      NONE = not in force close
///      CLOSED_INSOLVENT = (cross partyB mode) close succeeded but PartyB could not remain solvent when accounting for uPNL
///      CLOSED_SOLVENT = close succeeded without liquidation/insolvency
///      CLOSED_LIQUIDATED = (normal partyB mode) PartyB was liquidated during force close
///
///      Event mapping:
///      - Cross partyB mode: `ForceClosePosition(...)` is always emitted. If insolvent, `ForceClosePartyBInsolvent(...)` is also emitted.
///      - Normal partyB mode: `ForceClosePosition(...)` implies CLOSED_SOLVENT; `LiquidatePartyB(...)` implies CLOSED_LIQUIDATED.
enum PartyBForceCloseState {
	NONE,
	CLOSED_INSOLVENT,
	CLOSED_SOLVENT,
	CLOSED_LIQUIDATED
}

/// @notice Tracks PnL settlement between PartyA and PartyB during PartyA liquidation
/// @dev Used during PartyA liquidation to reconcile PnL with each PartyB.
///      expectedAmount = full PnL for PartyA's accumulated UPNL tracking
///      actualAmount = amount actually transferred to/from PartyB (may differ in OVERDUE due to deficit,
///                     or overridden via resolveLiquidationDispute)
///      cva = CVA returned to PartyB, pending = settlement in progress.
struct LiquidationSettlementState {
	int256 actualAmount;
	int256 expectedAmount;
	uint256 cva;
	bool pending;
}

/// @notice Complete state tracking for a force close operation on a position
/// @dev Force close is a multi-step process that lets PartyA close positions when PartyB
///      isn't responding. This struct tracks the workflow snapshot (uPNL/currentPrice),
///      the derived closePrice, and PartyB's resulting solvency. Note: inProgress is set during init but
///      does NOT prevent re-initialization - it only gates progression to subsequent steps.
///      The quote's status (CLOSE_PENDING) is the primary guard against invalid force closes.
struct ForceCloseDetail {
	/// @notice The latest Muon request id used to fill/refresh the force-close snapshot.
	/// @dev Observability-only metadata for off-chain correlation; NOT used in protocol logic.
	bytes priceSigId;
	/// @notice The quote id this struct corresponds to.
	/// @dev Redundant with the mapping key; kept for convenience in off-chain reads.
	uint256 quoteId;
	/// @notice Last time the workflow snapshot was updated (init/refresh/settle/finalize depending on flow).
	uint256 timestamp;
	/// @notice PartyB available balance after close (set on finalize).
	int256 partyBAvailableAfterClose;
	/// @notice The close price computed at initialization (kept stable across refreshes).
	uint256 closePrice;
	/// @notice Snapshot uPNL for PartyB used during finalize (can be refreshed/adjusted).
	int256 upnlPartyB;
	/// @notice Snapshot current price used during finalize (can be refreshed).
	uint256 currentPrice;
	/// @notice Final PartyB outcome for the force close workflow (set on finalize).
	PartyBForceCloseState partyBState;
	/// @notice Whether a 3-step force close workflow is active for this quoteId.
	bool inProgress;
}

/// @notice Complete liquidation state for a PartyA being liquidated
/// @dev This is the source of truth during PartyA liquidation. Contains everything needed
///      to process the liquidation: UPNL at time of insolvency, total unrealized losses,
///      any deficit that PartyB must cover, and the liquidator's fee. The disputed flag
///      allows challenging incorrect liquidations. involvedPartyBCounts tracks how many
///      hedgers have positions being liquidated.
struct LiquidationDetail {
	bytes liquidationId;
	LiquidationType liquidationType;
	int256 upnl;
	int256 totalUnrealizedLoss;
	uint256 deficit;
	uint256 liquidationFee;
	uint256 timestamp;
	uint256 involvedPartyBCounts;
	int256 partyAAccumulatedUpnl;
	bool disputed;
	uint256 liquidationTimestamp;
}

/// @notice A price snapshot at a specific time
/// @dev Used during liquidation to record prices at the moment of insolvency.
///      The timestamp ensures prices are fresh and match the liquidation event.
struct Price {
	uint256 price;
	uint256 timestamp;
}

/// @title AccountStorage
/// @notice All account balance and state data for PartyAs and PartyBs
/// @dev The heart of the accounting system. Every balance, locked amount, and account state
///      lives here.
library AccountStorage {
	bytes32 internal constant ACCOUNT_STORAGE_SLOT = keccak256("diamond.standard.storage.account");

	struct Layout {
		/// @notice Withdrawable balance per user (not yet committed to trading)
		/// @dev Users can withdraw from this (after cooldown) or allocate it for trading.
		///      Updated by: deposit, withdraw, deallocate, internal/external transfers.
		mapping(address => uint256) balances;
		/// @notice Funds committed to trading but not yet locked in positions
		/// @dev When PartyA allocates, funds move here. This is their "margin account".
		///      Can be used to open positions or deallocated back to balance.
		mapping(address => uint256) allocatedBalances;
		/// @notice Margin locked when a quote is sent but not yet opened
		/// @dev When PartyA sends a quote, required margin (CVA + LF + partyAmm) moves here.
		///      If PartyB opens the position, it moves to lockedBalances. If canceled, refunded.
		///      Contains CVA (credit valuation adjustment), LF (liquidation fee), partyAmm
		///      (PartyA maintenance margin).
		mapping(address => LockedValues) pendingLockedBalances;
		/// @notice Margin locked in open positions
		/// @dev Once a quote is opened, locked values move from pending to here. Released when
		///      position closes.
		mapping(address => LockedValues) lockedBalances;
		/// @notice PartyB's allocated balance per PartyA
		/// @dev In isolated mode, PartyB allocates separately for each PartyA they trade with.
		///      Maps partyB => partyA => amount. For cross-mode PartyB, address(0) is used
		///      as the master bucket instead of per-partyA allocations.
		mapping(address => mapping(address => uint256)) partyBAllocatedBalances;
		/// @notice PartyB's pending locked values per PartyA
		/// @dev Same as pendingLockedBalances but for the PartyB side of each trade.
		///      Tracks how much PartyB has committed to quotes not yet opened.
		mapping(address => mapping(address => LockedValues)) partyBPendingLockedBalances;
		/// @notice PartyB's locked values in open positions per PartyA
		/// @dev Same as lockedBalances but for the PartyB side.
		mapping(address => mapping(address => LockedValues)) partyBLockedBalances;
		/// @notice Timestamp of last deallocate action per user
		/// @dev Records when a user last deallocated funds. Used with MAStorage.withdrawCooldownPeriod
		///      to enforce a cooldown before withdrawals are allowed.
		mapping(address => uint256) deallocateTimestamp;
		/// @notice Replay protection counter for PartyA signatures
		/// @dev Incremented with each action that changes the UPNL of partyA.
		///      Muon signatures include this nonce to prevent replay attacks.
		mapping(address => uint256) partyANonces;
		/// @notice Replay protection counter for PartyB signatures per PartyA
		/// @dev PartyB has separate nonces for each PartyA they trade with. Both
		///      per-PartyA nonces AND the address(0) global nonce are always incremented
		///      on every upnl changing operation. This nonce will be ignored for cross partyBs
		///      when doing all operations except deallocation. The reason for that is to allow
		///      parallel operations to solver.
		mapping(address => mapping(address => uint256)) partyBNonces;
		/// @notice Accounts frozen by admin due to suspicious activity
		/// @dev Suspended users cannot open/close positions or have positions opened against them.
		///      Checked via notSuspended modifier. Used when investigating potential exploits
		///      or rule violations. Withdrawal requests have separate suspension handling.
		mapping(address => bool) suspendedAddresses;
		/// @notice Full liquidation state for PartyAs being liquidated
		/// @dev Contains everything about an ongoing liquidation: UPNL, deficit, type, timestamp, etc.
		mapping(address => LiquidationDetail) liquidationDetails;
		/// @notice Oracle prices set during liquidation per symbol
		/// @dev When liquidating, we lock in prices for each symbol at the moment of
		///      insolvency. Maps user => symbolId => Price. Used to close positions at
		///      consistent prices throughout the liquidation process.
		mapping(address => mapping(uint256 => Price)) symbolsPrices;
		/// @notice Addresses participating in a user's liquidation
		/// @dev Exactly two liquidators are recorded: [0] from liquidatePartyA/deferredLiquidatePartyA,
		///      [1] from setSymbolsPrice/determineLiquidationType. The liquidation fee is split
		///      50/50 between them. Cleared after liquidation completes.
		mapping(address => address[]) liquidators;
		/// @notice Reimbursement owed to PartyA, used by clearing house takeover flow
		/// @dev In CH takeover: stores pending fees added by liquidatePendingPositionsForClearingHouse.
		///      CH can pull via deallocateForClearingHouse(REIMBURSEMENT_KEY). Released at settlePartyATakeover.
		mapping(address => uint256) partyAReimbursement;
		/// @notice UPNL settlement state between PartyA-PartyB pairs during liquidation
		/// @dev Used during PartyA liquidation to track UPNL reconciliation with each PartyB.
		///      expectedAmount = full PnL for PartyA's accumulated UPNL tracking
		///      actualAmount = amount actually transferred (may differ in OVERDUE due to deficit,
		///                     or overridden via resolveLiquidationDispute)
		///      cva = CVA held for this PartyB, pending = settlement in progress.
		///      Cleared after liquidation completes via settlePartyALiquidation.
		mapping(address => mapping(address => LiquidationSettlementState)) settlementStates;
		/// @notice PartyB's reserve funds for covering force close scenarios
		/// @dev Extra collateral PartyB deposits as a safety buffer. Used during force close
		///      if their allocated balance is insufficient. Not used in cross mode.
		mapping(address => uint256) reserveVault;
		/// @notice List of PartyBs that PartyA has open positions with
		/// @dev Used for symbol access control - PartyA can only trade symbols that ALL connected
		///      PartyBs support (not blacklisted and whitelisted). Also enforces maxPartyAConnectionLimit.
		///      Added when first position opens with a PartyB, removed when last position closes.
		mapping(address => address[]) connectedPartyBs;
		/// @notice Fast lookup for whether PartyA has positions with a specific PartyB
		/// @dev O(1) check instead of iterating connectedPartyBs array.
		mapping(address => mapping(address => bool)) isConnectedPartyB;
		/// @notice State of force close operations per quote
		/// @dev Force close lets PartyA close positions when PartyB isn't responding.
		///      Tracks the multi-step process: settlement state, allocated balance state,
		///      PartyB solvency result. The inProgress flag gates step progression but does
		///      NOT prevent re-initialization - quote status is the primary guard.
		mapping(uint256 => ForceCloseDetail) forceCloseDetails;
		/// @notice Open trading fees reserved from PartyA allocated balance for pending or locked quotes
		mapping(address => uint256) partyAReservedOpenFees;
		/// @notice Escrowed funds from LATE/OVERDUE liquidations awaiting CH distribution
		/// @dev Created at settlement when liquidation type is LATE or OVERDUE. CH distributes via distributeLiquidationEscrow.
		///      Per-partyA (only one active liquidation per partyA). Accumulates if CH hasn't distributed before next liquidation.
		mapping(address => uint256) liquidationEscrow;
		/// @notice PartyA's excess balance from deferred liquidation (current balance minus historical insolvency point)
		/// @dev Always returned to partyA at settlement regardless of liquidation type. Not accessible by clearing house.
		mapping(address => uint256) partyADeferredBalance;
		/// @notice Conservative reserve of funds a cross-mode PartyB owes to pending PartyA liquidation settlements.
		/// @dev Equals the sum of max(0, actualAmount) across all pending settlementStates for this PartyB.
		///      Prevents cross-mode PartyB from extracting funds between liquidatePositionsPartyA and
		///      settlePartyALiquidation by subtracting this reserve from effective available balance
		///      during deallocateForPartyB.
		mapping(address => uint256) partyBLiquidationSettlementReserve;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = ACCOUNT_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/ClearingHouseStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Liquidation state for a cross-margin PartyB affecting all their counterparties
/// @dev Cross-margin (master account) PartyB liquidation is handled by the ClearingHouse
///      and affects all PartyAs at once.
///      inProgress prevents any actions with this PartyB during liquidation.
struct CrossLiquidationDetail {
	bytes liquidationId;
	int256 upnl;
	uint256 timestamp;
	uint256 deallocatedPool;
	bool inProgress;
}

/// @notice Takeover state for a PartyA liquidation being handled by the ClearingHouse
/// @dev When a PartyA liquidation gets stuck (e.g., due to Muon signature issues),
///      the ClearingHouse can take over and manually complete the liquidation.
///      inProgress prevents normal liquidation functions from running.
///      Structure mirrors CrossLiquidationDetail for consistency.
struct PartyATakeoverDetail {
	bytes liquidationId;
	uint256 deallocatedPool;
	bool inProgress;
}

/// @title ClearingHouseStorage
/// @notice Storage for ClearingHouse operations: cross PartyB liquidation and PartyA takeover
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library ClearingHouseStorage {
	bytes32 internal constant CLEARING_HOUSE_STORAGE_SLOT = keccak256("diamond.standard.storage.clearinghouse");

	struct Layout {
		/// @notice Liquidation state for cross PartyBs
		/// @dev Tracks cross-mode PartyB liquidation state (separate from AccountStorage.liquidationDetails which is for PartyA).
		mapping(address => CrossLiquidationDetail) crossLiquidationDetails;
		/// @notice Takeover state for PartyA liquidations
		/// @dev Maps partyA => PartyATakeoverDetail. When inProgress is true,
		///      the ClearingHouse has taken over the liquidation and normal
		///      liquidation functions are blocked.
		mapping(address => PartyATakeoverDetail) partyATakeoverDetails;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = CLEARING_HOUSE_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/ExternalTransferStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Status of an external transfer
/// @dev Tracks the lifecycle of external transfers to trusted targets (other Symmio diamonds or external contracts).
///      PENDING = initiated but not yet completed/canceled by provider
///      COMPLETED = provider accepted and deposited on target
///      CANCELED = user canceled
enum VirtualExternalTransferStatus {
	PENDING,
	COMPLETED,
	CANCELED
}

/// @notice Transfer request moving funds to a trusted target via a virtual provider
/// @dev Enables fund movement to any whitelisted target -- another Symmio diamond (e.g., perps and options)
///      or any trusted external contract. Uses virtual providers as intermediaries who credit the receiver
///      on the target. The provider must accept the transfer, or user can cancel.
struct VirtualExternalTransferRequest {
	uint256 id;
	address sender; // user in source contract
	address receiver; // recipient in target contract
	address source;
	address target;
	uint256 amount;
	uint256 timestamp;
	address provider; // virtual provider who handles the transfer
	VirtualExternalTransferStatus status;
}

/// @title ExternalTransferStorage
/// @notice Fund transfers to trusted external targets
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library ExternalTransferStorage {
	bytes32 internal constant EXTERNAL_TRANSFER_STORAGE_SLOT = keccak256("diamond.standard.storage.externaltransfer");

	struct Layout {
		/// @notice Counter for external transfer IDs
		/// @dev Auto-incremented when creating external transfers. Used as unique identifier
		///      for each external transfer request.
		uint256 lastExternalTransferId;
		/// @notice Stops cross protocol balance transfers when true
		/// @dev External transfers move funds between different protocols via
		///      relayer contracts. Pause this if the relayers are compromised.
		bool externalTransferPaused;
		/// @notice Relayer contracts authorized for external transfers to specific targets
		/// @dev Maps target address => authorized relayer. The relayer receives
		///      funds and deposits them on the target for the user.
		mapping(address => address) externalTransferTargetsRelayers;
		/// @notice External transfer request data by ID
		/// @dev Stores the full transfer request: sender, receiver, source/target contracts,
		///      amount, provider, and status. Provider must accept or user can cancel.
		mapping(uint256 => VirtualExternalTransferRequest) externalTransfers;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = EXTERNAL_TRANSFER_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/GlobalAppStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @title GlobalAppStorage
/// @notice Central configuration and pause state for the entire Symmio protocol
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
///      Most variables here are checked in modifiers across all facets.
library GlobalAppStorage {
	bytes32 internal constant GLOBAL_APP_STORAGE_SLOT = keccak256("diamond.standard.storage.global");

	struct Layout {
		/// @notice The ERC20 token used as collateral for all trading (e.g., USDC)
		/// @dev Can be changed by admin via setCollateral(), but only when the contract holds
		///      zero balance of the current collateral. All balances, locked values, and
		///      settlements are denominated in this token. Changing while funds exist would
		///      break accounting entirely.
		address collateral;
		/// @notice Where trading fees go in case of no affiliate or affiliate has no custom fee collector
		address defaultFeeCollector;
		/// @notice The big red button - stops everything when true
		/// @dev Checked first in every pausable operation via the Pausable modifier hierarchy.
		///      When this is on, nothing works: no deposits, no trading, no withdrawals,
		///      no liquidations. Only use in emergencies. All other pause flags are also
		///      checked against this - if globalPaused is true, nothing runs regardless of
		///      other pause states.
		bool globalPaused;
		/// @notice Stops all liquidation processing when true
		/// @dev Use this when liquidation logic has a bug or oracle issues would cause
		///      unfair liquidations. Positions can still be opened/closed, just not liquidated.
		bool liquidationPaused;
		/// @notice Stops balance-changing operations when true
		/// @dev Blocks deposits, withdrawals, allocations, and deallocations. Trading can
		///      continue with existing allocated funds. Useful when
		///      investigating suspicious balance activity.
		bool accountingPaused;
		/// @notice Stops all PartyB operations when true
		/// @dev PartyBs cannot lock quotes, open positions, or fill close requests.
		///      PartyA can still send quotes, but they'll sit pending.
		bool partyBActionsPaused;
		/// @notice Stops all PartyA (trader) operations when true
		/// @dev Users cannot send quotes, request closes, or cancel. PartyBs can still
		///      process existing requests. Rarely used - typically you'd pause specific
		///      users via suspendedAddresses instead.
		bool partyAActionsPaused;
		/// @notice Activates emergency mode for the entire protocol
		/// @dev When true, RESTRICTS normal PartyB operations (position opens, batch actions)
		///      and ENABLES emergency close positions.
		bool emergencyMode;
		/// @notice Limit checked when users allocate funds for trading
		/// @dev Only enforced at allocation time via allocate() and internalTransfer().
		///      NOT a hard cap - users can exceed this through trading profits or if
		///      the limit is lowered after they already allocated. Used for gradual
		///      rollouts or regulatory compliance.
		uint256 balanceLimitPerUser;
		/// @notice Tracks which PartyBs are in emergency mode
		/// @dev When true for a PartyB, enables emergencyClosePosition for quotes with that
		///      PartyB INDEPENDENTLY of global emergencyMode. Allows surgical wind-down of
		///      specific PartyBs without affecting the rest of the protocol.
		mapping(address => bool) partyBEmergencyStatus;
		/// @notice Role-based access control: who can do what
		/// @dev Maps user address => role hash => has_role. Roles are keccak256 hashes of
		///      role names (e.g., keccak256("SETTER_ROLE")). Checked via LibAccessibility.hasRole()
		///      in the onlyRole modifier.
		mapping(address => mapping(bytes32 => bool)) hasRole;
		/// @notice Stops internal balance transfers between accounts when true
		/// @dev Internal transfers let users move funds between their own accounts on the
		///      same diamond without withdrawal cooldown. Pause this if you suspect abuse
		///      or need to freeze fund movements during an investigation.
		bool internalTransferPaused;
		/// @notice Custom fee collector address per affiliate
		/// @dev Maps affiliate address => their fee collector. If not set (zero address),
		///      falls back to defaultFeeCollector.
		mapping(address => address) affiliateFeeCollector;
		/// @notice External contract that validates Muon signatures
		/// @dev Decoupled from main contract to support multiple signers and key rotation.
		///      All Muon signature checks go through this contract. If this is wrong or
		///      compromised, signature verification breaks entirely.
		address signatureVerifier;
		/// @notice Who can grant/revoke each role
		/// @dev Maps role hash => admin address => is_admin. Role admins can modify hasRole
		///      for their role.
		mapping(bytes32 => mapping(address => bool)) roleAdmins;
		/// @notice Stops PartyBs from opening new positions when true
		/// @dev PartyBs can still fill close requests and manage existing positions, but
		///      cannot lock or open new quotes. Useful during maintenance or when restricting
		///      new position creation while winding down.
		bool partyBOpenPositionsPaused;
		/// @notice Disables the legacy deallocate function when true
		/// @dev The old version signature was not unique and therefore muon had no control over it.
		bool legacyDeallocateDeprecated;
		/// @notice Address that receives soft liquidation penalty funds from cross PartyBs
		/// @dev When a cross-margin PartyB is subject to a soft liquidation via the ClearingHouse,
		///      the penalty amount is transferred to this address's balance.
		address softLiquidationPenaltyCollector;
		/// @notice Current signer for meta-transaction/proxy pattern
		/// @dev When a proxy calls on behalf of a user, this is set to the actual user.
		///      LibSigner.getSigner() returns this if set, otherwise msg.sender.
		///      Used to support gasless transactions and account abstraction.
		address signer;
		/// @notice Stops instant layer operations when true
		/// @dev The instant layer enables fast trading for PartyAs. When paused,
		///      instant actions revert but normal trading continues.
		bool instantLayerPaused;
		/// @notice Flag indicating calls should be treated as instant layer operations
		/// @dev Set via setCallFromInstantLayer() by authorized callers. This is a persistent
		///      state flag, not automatically reset - the caller must manage its lifecycle.
		///      When true, instant actions mode checks pass for bound PartyAs. Checked in
		///      Accessibility modifiers to allow/restrict certain operations.
		bool callFromInstantLayer;
		/// @notice Master switch for cross (master account) mode
		/// @dev When false, PartyBs cannot activate cross mode. This is the global
		///      gate - individual PartyBs still need to activate separately.
		///      Once activated, turning this off doesn't affect existing
		///      cross PartyBs.
		bool crossPartyBModeActivated;
		/// @notice Skip pending balance tracking in atomic send+lock+open flows
		/// @dev When true, sendQuote/lockQuote skip writing to pending balances/arrays,
		///      and openPosition skips removing them. Eliminates ~24 wasted SSTOREs.
		///      Set via setInstantOpenMode() by the instant layer around template execution.
		///      IMPORTANT: Appended after crossPartyBModeActivated to preserve storage layout.
		bool instantOpenMode;
		/// @notice Per-PartyB flag that prevents a specific PartyB from locking or opening new positions
		/// @dev When true for a PartyB, blocks lockQuote and openPosition (both single and batch).
		///      Unlike deregisterPartyB, this keeps partyBStatus=true so the PartyB can still:
		///      - Close existing positions (fillCloseRequest, emergencyClosePosition)
		///      - Deallocate funds (deallocateForPartyB)
		///      - Receive correct routing in distributeFromLiquidationEscrow / distributeForClearingHouse
		///      Use this instead of deregisterPartyB when winding down a PartyB.
		mapping(address => bool) partyBOpenPositionsPausedPerPartyB;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = GLOBAL_APP_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
