    "project/contracts/core/storages/MAStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Display and branding metadata for protocol entities (PartyBs, affiliates)
/// @dev Stored on-chain for discoverability. Frontend UIs can read this to display
///      hedger/affiliate information without needing off-chain databases.
struct EntityMetadata {
	string name;
	string brandColor;
	string metadata;
}

/// @title MAStorage - Master Agreement Storage
/// @notice Protocol parameters and configuration for trading rules and timing
/// @dev These are the "knobs" that control protocol behavior: cooldowns, fees, limits.
///      Most values are set by admins and affect all users. Change with extreme care -
///      wrong values can break liquidations, enable exploits, or lock user funds.
library MAStorage {
	bytes32 internal constant MA_STORAGE_SLOT = keccak256("diamond.standard.storage.masteragreement");

	struct Layout {
		/// @notice How long users must wait after deallocating before they can withdraw
		/// @dev This cooldown exists for off-chain monitoring to detect suspicious activity.
		///      Typically 12 hours. Previously named deallocateCooldown.
		uint256 withdrawCooldownPeriod;
		/// @notice How long PartyA must wait before force-canceling a pending quote
		/// @dev Gives PartyB time to respond to a quote cancel request before PartyA can unilaterally cancel.
		uint256 forceCancelCooldown;
		/// @notice How long PartyA must wait before force-canceling a close request
		/// @dev Same concept as forceCancelCooldown but for close requests instead of quotes.
		uint256 forceCancelCloseCooldown;
		/// @notice Minimum time after close request before force close price window can start
		/// @dev The HighLowPriceSig's startTime must be >= quote.statusModifyTimestamp + forceCloseFirstCooldown.
		///      Ensures PartyB has enough time to consider and respond to the close request
		///      before PartyA can use price data for force close.
		uint256 forceCloseFirstCooldown;
		/// @notice Maximum age of price signatures used during PartyB liquidation
		/// @dev Price signature timestamp must be <= partyBLiquidationTimestamp + liquidationTimeout.
		///      Ensures prices used to close positions during liquidation are timely and
		///      relevant to when the liquidation was initiated.
		uint256 liquidationTimeout;
		/// @notice Percentage of remaining LF for the initiating liquidator in PartyB liquidation (18 decimals)
		/// @dev When liquidatePartyB is called, if LF exceeds the deficit:
		///      remainingLf = partyBLockedBalances.lf - deficit
		///      initiatorShare = remainingLf * liquidatorShare / 1e18 → goes to liquidatePartyB caller
		///      The rest is divided per-position via partyBPositionLiquidatorsShare for position liquidators.
		uint256 liquidatorShare;
		/// @notice Maximum number of pending quotes a PartyA can have at once
		/// @dev Prevents spam and limits exposure calculation complexity. If a user hits
		///      this limit, they must wait for existing quotes to resolve before sending more.
		uint256 pendingQuotesValidLength;
		/// @notice DEPRECATED - Previously set force close gap ratio globally
		/// @dev Now handled per-symbol via SymbolStorage.forceCloseGapRatio. Kept for
		///      storage layout compatibility. Do not use.
		uint256 deprecatedForceCloseGapRatio;
		/// @notice Whether an address is registered as a PartyB (market maker)
		/// @dev Only registered PartyBs can lock and open positions. This is the whitelist.
		///      Removing a PartyB doesn't close their positions - they just can't open new ones.
		mapping(address => bool) partyBStatus;
		/// @notice Whether an address can perform liquidations
		/// @dev Liquidator whitelist. Prevents random addresses from griefing liquidations.
		///      In practice, often set to specific keeper bots.
		mapping(address => bool) liquidationStatus;
		/// @notice Whether a specific PartyB-PartyA pair is being liquidated
		/// @dev Maps partyB => partyA => isLiquidating. Prevents actions on positions
		///      while liquidation is in progress.
		mapping(address => mapping(address => bool)) partyBLiquidationStatus;
		/// @notice When liquidation started for a PartyB-PartyA pair
		/// @dev Maps partyB => partyA => timestamp. Used for timeout calculations
		///      and dispute windows.
		mapping(address => mapping(address => uint256)) partyBLiquidationTimestamp;
		/// @notice Per-position LF share for liquidators closing positions in PartyB liquidation
		/// @dev Calculated during liquidatePartyB: (remainingLf - initiatorShare) / positionsCount.
		///      Maps partyB => partyA => sharePerPosition. Liquidators calling liquidatePositionsPartyB
		///      receive this amount multiplied by the number of positions they close.
		mapping(address => mapping(address => uint256)) partyBPositionLiquidatorsShare;
		/// @notice Array of all registered PartyB addresses
		/// @dev Used for iteration (e.g., listing all hedgers in a view function).
		///      Kept in sync with partyBStatus mapping - when registering/unregistering,
		///      both are updated.
		address[] partyBList;
		/// @notice Required time gap between price window end and force close execution
		/// @dev The HighLowPriceSig's endTime must be <= block.timestamp - forceCloseSecondCooldown,
		///      AND endTime + forceCloseSecondCooldown <= quote.deadline. Ensures PartyB had
		///      sufficient time after the price window to fill the close request normally.
		uint256 forceCloseSecondCooldown;
		/// @notice Price penalty applied during force close (18 decimals, e.g., 1e16 = 1%)
		/// @dev For LONG: closePrice = max(requestedPrice + penalty, averagePrice).
		///      For SHORT: closePrice = min(requestedPrice - penalty, averagePrice).
		///      PartyB gets a worse price as penalty for not responding to close requests.
		uint256 forceClosePricePenalty;
		/// @notice Minimum price window duration when average price is used in force close
		/// @dev When force close uses the averagePrice (to protect against extreme moves),
		///      the window (endTime - startTime) must exceed this value. Ensures price
		///      averaging covers a meaningful time period to prevent manipulation.
		uint256 forceCloseMinSigPeriod;
		/// @notice Minimum time between consecutive deallocate operations
		/// @dev Different from deallocateCooldown - this is debounce between deallocates,
		///      not between deallocate and withdraw. Prevents rapid-fire deallocations.
		uint256 deallocateDebounceTime;
		/// @notice Whether an address is a registered affiliate
		/// @dev Affiliates can set custom fees and receive fee revenue. Must be registered
		///      here before their affiliate address can be used in quotes.
		mapping(address => bool) affiliateStatus;
		/// @notice Minimum time between UPNL settlements by the same third-party signer
		/// @dev Only enforced when: (1) not a force close operation, AND (2) signer != partyB.
		///      PartyB settling their own positions and force close operations bypass this.
		///      Prevents third parties from spamming settlements on the same partyB-partyA pair.
		uint256 settlementCooldown;
		/// @notice Timestamp of last UPNL settlement by each third-party signer
		/// @dev Maps signer => partyB => partyA => timestamp. Only updated/checked when
		///      signer != partyB and not force close. Used with settlementCooldown to
		///      rate-limit third-party settlement calls.
		mapping(address => mapping(address => mapping(address => uint256))) lastUpnlSettlementTimestamp;
		/// @notice Address that receives excess liquidation fees above the profit cap
		/// @dev During PartyA liquidation, if remainingLf > maxLiquidationProfitPerPosition * positionsCount,
		///      the excess goes here. Funds accumulate in this address's balance for later manual redistribution by the address owner.
		address liquidationInsuranceVault;
		/// @notice Cap on profit a liquidator can make from a single position
		/// @dev Prevents excessive liquidator profits on large positions. Excess goes
		///      to insurance vault.
		uint256 maxLiquidationProfitPerPosition;
		/// @notice Display metadata for registered entities
		/// @dev Maps entity address => metadata. Used by frontends to show hedger
		///      and affiliate branding information.
		mapping(address => EntityMetadata) entitiesMetadata;
		/// @notice Maximum number of PartyBs a PartyA can have open positions with
		/// @dev When checking if a symbol is allowed for PartyA, we loop through all connected
		///      PartyBs to verify none have blacklisted it. This limit bounds that loop's gas cost.
		///      If at limit, must close positions with one PartyB before opening with another.
		uint256 maxPartyAConnectionLimit;
		/// @notice Whether a PartyB can use auto-deleveraging to close positions unilaterally
		/// @dev When enabled, PartyB can call adlClose() to close positions at a specified price
		///      without PartyA consent. Used for risk management. Enabled by PARTY_B_MANAGER_ROLE.
		mapping(address => bool) adlEnabled;
		/// @notice Timestamp of last liquidator action for a PartyA
		/// @dev Updated on every liquidation step (setSymbolsPrice, liquidatePositions, etc.)
		///      Can be used later to enforce timeouts if liquidators become inactive.
		mapping(address => uint256) partyALiquidatorLastActionTimestamp;
		/// @notice Whether a PartyB is operating in cross (master account) mode
		/// @dev Cross-margin PartyBs have one shared balance across all PartyAs instead of
		///      isolated per-PartyA allocations. When true, uses address(0) for allocation
		///      mappings and has different liquidation flow via ClearingHouse.
		mapping(address => bool) crossModeEnabledForPartyB;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = MA_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/QuoteStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Direction of a trading position
enum PositionType {
	LONG,
	SHORT
}

/// @notice Type of order execution
enum OrderType {
	LIMIT,
	MARKET
}

/// @notice Lifecycle status of a quote from creation through settlement
enum QuoteStatus {
	PENDING, //0
	LOCKED, //1
	CANCEL_PENDING, //2
	CANCELED, //3
	OPENED, //4
	CLOSE_PENDING, //5
	CANCEL_CLOSE_PENDING, //6
	CLOSED, //7
	LIQUIDATED, //8
	EXPIRED, //9
	LIQUIDATED_PENDING //10
}

/// @notice Margin components locked for a position (CVA, liquidation fee, maintenance margins)
struct LockedValues {
	uint256 cva;
	uint256 lf;
	uint256 partyAmm;
	uint256 partyBmm;
}

/// @notice Full state of a trading quote or open position
struct Quote {
	uint256 id;
	address[] partyBsWhiteList;
	uint256 symbolId;
	PositionType positionType;
	OrderType orderType;
	uint256 openedPrice;
	uint256 initialOpenedPrice;
	uint256 requestedOpenPrice;
	uint256 marketPrice;
	uint256 quantity;
	uint256 closedAmount;
	LockedValues initialLockedValues;
	LockedValues lockedValues;
	uint256 maxFundingRate;
	address partyA;
	address partyB;
	QuoteStatus quoteStatus;
	uint256 avgClosedPrice;
	uint256 requestedClosePrice;
	uint256 quantityToClose;
	uint256 parentId;
	uint256 createTimestamp;
	uint256 statusModifyTimestamp;
	uint256 lastFundingPaymentTimestamp;
	uint256 deadline;
	uint256 tradingFee;
	address affiliate;
	int256 accumulatedPaidFunding;
	uint256 closeFee;
	bytes data;
}

/// @notice Custom fee overrides for a specific PartyB-symbol pair
struct Fee {
	uint256 openFee;
	uint256 closeFee;
	bool isSet;
}

/// @title QuoteStorage
/// @notice All quote/position data and aggregated metrics for efficient calculations
library QuoteStorage {
	bytes32 internal constant QUOTE_STORAGE_SLOT = keccak256("diamond.standard.storage.quote");

	struct Layout {
		/// @notice All quote IDs created by each user
		/// @dev Historical record of every quote a PartyA has ever created. Used for
		///      querying user's trading history. Only grows, never shrinks.
		mapping(address => uint256[]) quoteIdsOf;
		/// @notice The actual Quote data keyed by quote ID
		/// @dev The source of truth for all position data.
		mapping(uint256 => Quote) quotes;
		/// @notice Count of open positions per PartyA
		/// @dev Used for quick checks like "does this user have any positions?".
		mapping(address => uint256) partyAPositionsCount;
		/// @notice Count of open positions per PartyB-PartyA pair, plus global totals
		/// @dev Maps partyB => partyA => count for per-counterparty tracking.
		///      Additionally, partyB => address(0) always tracks total positions
		///      across all PartyAs, used for cross PartyB operations.
		mapping(address => mapping(address => uint256)) partyBPositionsCount;
		/// @notice Quote IDs not yet opened per PartyA
		/// @dev Contains quotes in PENDING, LOCKED, or CANCEL_PENDING status. Removed
		///      when opened, canceled, or expired. Used to iterate pending orders.
		mapping(address => uint256[]) partyAPendingQuotes;
		/// @notice Quote IDs that PartyB has locked per PartyA
		/// @dev Maps partyB => partyA => quoteIds[]. Added when PartyB locks a quote,
		///      removed when quote opens or is canceled. Contains LOCKED or CANCEL_PENDING.
		mapping(address => mapping(address => uint256[])) partyBPendingQuotes;
		/// @notice Active position quote IDs per PartyA
		/// @dev Added when quote opens, removed when closes/liquidates. Contains quotes
		///      with OPENED, CLOSE_PENDING, CANCEL_CLOSE_PENDING, or LIQUIDATED_PENDING.
		mapping(address => uint256[]) partyAOpenPositions;
		/// @notice Index of each quote in partyAOpenPositions array
		/// @dev Enables O(1) removal from partyAOpenPositions by swapping with last element.
		///      Maps quoteId => index in array. Must stay in sync with the array.
		mapping(uint256 => uint256) partyAPositionsIndex;
		/// @notice Active position quote IDs per PartyB-PartyA pair
		/// @dev Maps partyB => partyA => quoteIds[]. Same statuses as partyAOpenPositions.
		mapping(address => mapping(address => uint256[])) partyBOpenPositions;
		/// @notice Index of each quote in partyBOpenPositions array
		/// @dev Same as partyAPositionsIndex but for PartyB arrays. Enables O(1) removal.
		mapping(uint256 => uint256) partyBPositionsIndex;
		/// @notice Auto-incrementing counter for quote IDs
		/// @dev Initialized to 0 (Solidity default). First quote gets ID 1 via ++lastId.
		///      Never decreases. ID 0 is never assigned, so it can be used as "null"
		///      or "not found" in mappings and comparisons.
		uint256 lastId;
		/// @notice Auto-incrementing counter for close operation IDs
		/// @dev Each close request gets a unique ID for tracking and event correlation.
		uint256 lastCloseId;
		/// @notice Maps quote ID to its current close operation ID
		/// @dev When a close is requested, this links the quote to its close ID.
		///      Used to match close events to specific close requests.
		mapping(uint256 => uint256) closeIds;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = QUOTE_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/TradingModeStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice The three states of PartyA-PartyB binding
/// @dev Binding is required for instant actions mode.
///      NOT_BOUND = can trade with any PartyB
///      BOUND = locked to one PartyB (required for instant actions)
///      PENDING_UNBIND = waiting for unbind cooldown to complete
enum BindStatus {
	NOT_BOUND,
	BOUND,
	PENDING_UNBIND
}

/// @notice PartyA's binding state to a specific PartyB for instant and oracle-less trading
/// @dev Binding is required for instant actions mode. Once bound, PartyA can only trade
///      with their bound PartyB. modifyTimestamp tracks when binding changed for cooldown.
struct BindState {
	BindStatus status;
	address partyB;
	uint256 modifyTimestamp;
}

/// @title TradingModeStorage
/// @notice PartyA binding and instant layer features
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library TradingModeStorage {
	bytes32 internal constant TRADING_MODE_STORAGE_SLOT = keccak256("diamond.standard.storage.tradingmode");

	struct Layout {
		/// @notice PartyA's binding state to a specific PartyB
		/// @dev Enables oracle-less trading. Required for instant actions. When bound,
		///      PartyA can only trade with their bound PartyB.
		///      Contains status (NOT_BOUND/BOUND/PENDING_UNBIND), the partyB
		///      address, and timestamp for unbind cooldown tracking.
		mapping(address => BindState) bindState;
		/// @notice Whether PartyB is allowed to be bound to PartyAs
		/// @dev If false, PartyAs cannot bind to this PartyB. Not every solver is allowed to
		///      have oracle-less trading.
		mapping(address => bool) isPartyBBindable;
		/// @notice Whether PartyA has instant actions mode enabled
		/// @dev Instant mode allows solver to be sure that partyA is not going to do any on-chain actions.
		///      Requires PartyA to be bound to a specific PartyB first.
		mapping(address => bool) instantActionsMode;
		/// @notice When PartyA's instant actions mode deactivation can be finalized
		/// @dev Deactivating instant mode is a two-step process: request deactivation, wait
		///      for cooldown, then finalize. This stores when the cooldown ends.
		mapping(address => uint256) instantActionsModeDeactivateTime;
		/// @notice How long to wait before instant actions mode deactivation completes
		/// @dev Prevents instant on/off toggling that could be used to game the solvers.
		uint256 deactiveInstantActionModeCooldown;
		/// @notice How long PartyA must wait to complete unbinding from PartyB
		/// @dev Unbinding is a two-step process: request, wait cooldown, complete.
		///      Prevents instant unbinding that could be used to dodge obligations.
		uint256 unbindCooldown;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = TRADING_MODE_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/utils/Accessibility.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

import { MAStorage } from "../storages/MAStorage.sol";
import { GlobalAppStorage } from "../storages/GlobalAppStorage.sol";
import { AccountStorage } from "../storages/AccountStorage.sol";
import { Quote, QuoteStatus, QuoteStorage } from "../storages/QuoteStorage.sol";
import { TradingModeStorage } from "../storages/TradingModeStorage.sol";
import { ClearingHouseStorage } from "../storages/ClearingHouseStorage.sol";
import { LibAccessibility } from "../libraries/LibAccessibility.sol";
import { LibSigner } from "../libraries/LibSigner.sol";

abstract contract Accessibility {
	modifier onlyPartyB() {
		require(MAStorage.layout().partyBStatus[LibSigner.getSigner()], "Accessibility: Should be partyB");
		_;
	}

	modifier notPartyB() {
		require(!MAStorage.layout().partyBStatus[LibSigner.getSigner()], "Accessibility: Shouldn't be partyB");
		_;
	}

	modifier userNotPartyB(address user) {
		require(!MAStorage.layout().partyBStatus[user], "Accessibility: Shouldn't be partyB");
		_;
	}

	/// @notice Restricts function access to accounts that are admins for a specific role.
	/// @dev Includes proxy protection by default. When a proxy sets a signer before forwarding calls,
	///      `msg.sender` becomes the proxy address. Without the proxy check, functions would authorize
	///      based on the proxy's roles rather than the original caller's - allowing users to inherit
	///      any privileged roles held by the proxy.
	modifier onlyRoleAdmin(bytes32 role) {
		require(GlobalAppStorage.layout().signer == address(0), "Accessibility: Cannot call via proxy");
		require(LibAccessibility.isRoleAdmin(msg.sender, role), "Accessibility: Must be role admin");
		_;
	}

	/// @notice Restricts function access to accounts with a specific role.
	/// @dev Includes proxy protection by default. When a proxy sets a signer before forwarding calls,
	///      `msg.sender` becomes the proxy address. Without the proxy check, functions would authorize
	///      based on the proxy's roles rather than the original caller's - allowing users to inherit
	///      any privileged roles held by the proxy.
	///
	///      For functions that proxies legitimately need to call (e.g., setSigner), use onlyRoleAllowProxy instead.
	modifier onlyRole(bytes32 role) {
		require(GlobalAppStorage.layout().signer == address(0), "Accessibility: Cannot call via proxy");
		require(LibAccessibility.hasRole(msg.sender, role), "Accessibility: Must have role");
		_;
	}

	/// @notice Same as onlyRole but allows calls through proxies that set a signer.
	/// @dev USE WITH CAUTION. Only use this for functions that:
	///      1. Must be callable by proxies to function correctly (e.g., setSigner for proxy context setup)
	///      2. Have been explicitly reviewed for proxy-related security implications
	///
	///      If a proxy holds the required role, any user routing calls through that proxy will pass
	///      this check. Ensure this is the intended behavior before using this modifier.
	modifier onlyRoleAllowProxy(bytes32 role) {
		require(LibAccessibility.hasRole(msg.sender, role), "Accessibility: Must have role");
		_;
	}

	modifier notLiquidatedPartyA(address partyA) {
		require(!MAStorage.layout().liquidationStatus[partyA], "Accessibility: PartyA isn't solvent");
		_;
	}

	modifier notLiquidatedPartyB(address partyB, address partyA) {
		require(!MAStorage.layout().partyBLiquidationStatus[partyB][partyA], "Accessibility: PartyB isn't solvent");
		require(!ClearingHouseStorage.layout().crossLiquidationDetails[partyB].inProgress, "Accessibility: PartyB isn't solvent");
		_;
	}

	modifier notCrossLiquidatedPartyB(address partyB) {
		require(!ClearingHouseStorage.layout().crossLiquidationDetails[partyB].inProgress, "Accessibility: PartyB isn't solvent");
		_;
	}

	modifier notLiquidated(uint256 quoteId) {
		Quote storage quote = QuoteStorage.layout().quotes[quoteId];
		require(!MAStorage.layout().liquidationStatus[quote.partyA], "Accessibility: PartyA isn't solvent");
		require(!MAStorage.layout().partyBLiquidationStatus[quote.partyB][quote.partyA], "Accessibility: PartyB isn't solvent");
		require(!ClearingHouseStorage.layout().crossLiquidationDetails[quote.partyB].inProgress, "Accessibility: PartyB isn't solvent");
		require(
			quote.quoteStatus != QuoteStatus.LIQUIDATED &&
				quote.quoteStatus != QuoteStatus.LIQUIDATED_PENDING &&
				quote.quoteStatus != QuoteStatus.CLOSED,
			"Accessibility: Invalid state"
		);
		_;
	}

	modifier onlyPartyAOfQuote(uint256 quoteId) {
		Quote storage quote = QuoteStorage.layout().quotes[quoteId];
		require(quote.partyA == LibSigner.getSigner(), "Accessibility: Should be partyA of quote");
		_;
	}

	modifier onlyPartyBOfQuote(uint256 quoteId) {
		Quote storage quote = QuoteStorage.layout().quotes[quoteId];
		require(quote.partyB == msg.sender, "Accessibility: Should be partyB of quote");
		_;
	}

	modifier notSuspended(address user) {
		require(!AccountStorage.layout().suspendedAddresses[user], "Accessibility: Sender is Suspended");
		_;
	}

	modifier onlySuspended(address user) {
		require(AccountStorage.layout().suspendedAddresses[user], "Accessibility: User is not suspended");
		_;
	}

	modifier whenInstantModeIsNotActive(address sender) {
		require(
			!TradingModeStorage.layout().instantActionsMode[sender] || GlobalAppStorage.layout().callFromInstantLayer,
			"Accessibility: Instant Mode Active"
		);
		_;
	}
}
"
    },
    "project/contracts/core/utils/Pausable.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

import { GlobalAppStorage } from "../storages/GlobalAppStorage.sol";
import { ExternalTransferStorage } from "../storages/ExternalTransferStorage.sol";

abstract contract Pausable {
	modifier whenNotGlobalPaused() {
		require(!GlobalAppStorage.layout().globalPaused, "Pausable: Global paused");
		_;
	}

	modifier whenNotLiquidationPaused() {
		require(!GlobalAppStorage.layout().globalPaused, "Pausable: Global paused");
		require(!GlobalAppStorage.layout().liquidationPaused, "Pausable: Liquidation paused");
		_;
	}

	modifier whenNotAccountingPaused() {
		require(!GlobalAppStorage.layout().globalPaused, "Pausable: Global paused");
		require(!GlobalAppStorage.layout().accountingPaused, "Pausable: Accounting paused");
		_;
	}

